package com.aistock.market.realization;
import com.aistock.market.version.MarketVersionRepository;import com.aistock.common.BusinessException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.sql.Timestamp;import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;
import static com.aistock.market.realization.RealizationRecords.*;
public final class RealizationRepository {
 private final MarketVersionRepository market;private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final Clock clock;private final TransactionTemplate tx;
 public RealizationRepository(MarketVersionRepository market,ObjectMapper mapper,Clock clock){this.market=market;this.jdbc=market.jdbc();this.mapper=mapper;this.clock=clock;this.tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));}
 public Receipt begin(Request r,String hash){return tx.execute(s->{var inserted=jdbc.update("insert ignore into realization_operation(operation_id,request_hash,state,lease_until,created_at) values(?,?,'RUNNING',?,?)",r.operationId().toString(),hash,Timestamp.from(r.leaseUntil()),Timestamp.from(clock.instant()));var row=jdbc.queryForMap("select * from realization_operation where operation_id=? for update",r.operationId().toString());if(!hash.equals(row.get("request_hash")))throw error("REALIZATION_OPERATION_CONFLICT",HttpStatus.CONFLICT);if(inserted==1)return null;if("RUNNING".equals(row.get("state"))&&expired(r.operationId())){finishSql(r.operationId(),"FAILED",null,"ATTEMPT_EXPIRED");return new Receipt(r.operationId(),"FAILED",null,"ATTEMPT_EXPIRED");}return receipt(r.operationId(),row);});}
 public Head head(String instrument){return head(instrument,null);}
 public Head head(String instrument,LocalDate requiredThrough){return com.aistock.market.marketlifecycle.MarketEvidenceGate.local(()->{var pinned=com.aistock.market.marketlifecycle.MarketEvidenceGate.pinned(instrument);var rows=pinned==null?jdbc.queryForList("select v.* from market_data_version v join instrument_data_head h on h.version_id=v.version_id where h.instrument_id=? and h.provider='baostock' and h.price_basis='RAW' and v.instrument_id=? and v.provider='baostock' and v.price_basis='RAW' and v.status='AVAILABLE'",instrument,instrument):jdbc.queryForList("select * from market_data_version where version_id=? and instrument_id=? and provider='baostock' and price_basis='RAW' and status='AVAILABLE'",pinned,instrument);if(rows.isEmpty())throw error("REALIZATION_RAW_UNAVAILABLE",HttpStatus.CONFLICT);var row=rows.get(0);var coverage=(java.sql.Date)row.get("coverage_end");
  var calendar=(java.sql.Date)row.get("calendar_end");
  if(requiredThrough!=null && coverage.toLocalDate().isBefore(requiredThrough)
      && (calendar==null || calendar.toLocalDate().isBefore(requiredThrough)))
   throw error("REALIZATION_RAW_UNAVAILABLE",HttpStatus.CONFLICT);
  String id=(String)row.get("version_id");return new Head(id,(String)row.get("content_hash"),market.bars(id));});}
 public Receipt publish(Request r,Evidence evidence){return com.aistock.market.marketlifecycle.MarketEvidenceGate.local(()->{com.aistock.market.marketlifecycle.MarketEvidenceGate.raw(evidence.rawVersionId());return tx.execute(s->{var row=jdbc.queryForMap("select * from realization_operation where operation_id=? for update",r.operationId().toString());if(!"RUNNING".equals(row.get("state")))return receipt(r.operationId(),row);com.aistock.market.marketlifecycle.MarketEvidenceGate.publishable(jdbc,evidence.rawVersionId());checkLease(r);var ids=jdbc.queryForList("select version_id from realization_version where content_hash=?",String.class,evidence.contentHash());String id=ids.isEmpty()?UUID.randomUUID().toString():ids.get(0);var e=new Evidence(id,evidence.instrumentId(),evidence.provider(),evidence.definition(),evidence.originDate(),evidence.targetDates(),evidence.dueThrough(),evidence.rawVersionId(),evidence.rawContentHash(),evidence.sourcePayloadHash(),evidence.calendarHash(),evidence.contentHash(),evidence.capturedAt(),evidence.originRawClose(),evidence.originBackwardClose(),evidence.observations(),evidence.calendar());if(ids.isEmpty()){jdbc.update("insert into realization_version(version_id,instrument_id,content_hash,raw_version_id,evidence_json,created_at) values(?,?,?,?,?,?) on duplicate key update version_id=version_id",id,e.instrumentId(),e.contentHash(),e.rawVersionId(),json(e),Timestamp.from(clock.instant()));id=jdbc.queryForObject("select version_id from realization_version where content_hash=? for update",String.class,e.contentHash());}finishSql(r.operationId(),"AVAILABLE",id,null);checkLease(r);return new Receipt(r.operationId(),"AVAILABLE",id,null);});});}
 public Receipt finish(UUID operation,String state,String code){return tx.execute(s->{var row=jdbc.queryForMap("select * from realization_operation where operation_id=? for update",operation.toString());if(!"RUNNING".equals(row.get("state")))return receipt(operation,row);finishSql(operation,state,null,code);return new Receipt(operation,state,null,code);});}
 private void finishSql(UUID op,String state,String version,String error){jdbc.update("update realization_operation set state=?,version_id=?,error_code=?,finished_at=? where operation_id=? and state='RUNNING'",state,version,error,Timestamp.from(clock.instant()),op.toString());}
 public Receipt operation(UUID id){return tx.execute(s->{var rows=jdbc.queryForList("select * from realization_operation where operation_id=? for update",id.toString());if(rows.isEmpty())throw error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);var row=rows.get(0);if("RUNNING".equals(row.get("state"))&&expired(id)){finishSql(id,"FAILED",null,"ATTEMPT_EXPIRED");return new Receipt(id,"FAILED",null,"ATTEMPT_EXPIRED");}return receipt(id,row);});}
 public Evidence version(UUID id){return com.aistock.market.marketlifecycle.MarketEvidenceGate.local(()->{var rows=jdbc.queryForList("select evidence_json from realization_version where version_id=?",String.class,id.toString());if(rows.isEmpty())throw error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);try{var result=mapper.readValue(rows.get(0),Evidence.class);com.aistock.market.marketlifecycle.MarketEvidenceGate.raw(result.rawVersionId());return result;}catch(com.aistock.common.BusinessException e){throw e;}catch(Exception e){throw error("REALIZATION_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}});}
 private boolean expired(UUID id){return jdbc.queryForObject("select count(*) from realization_operation where operation_id=? and lease_until<=?",Integer.class,id.toString(),Timestamp.from(clock.instant()))==1;}
 private Receipt receipt(UUID id,Map<String,Object> row){return new Receipt(id,(String)row.get("state"),(String)row.get("version_id"),(String)row.get("error_code"));}
 private void checkLease(Request r){if(!clock.instant().isBefore(r.leaseUntil()))throw RealizationValidator.error("ATTEMPT_EXPIRED");}
 private String json(Object object){try{return mapper.writeValueAsString(object);}catch(Exception e){throw error("REALIZATION_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}}
 private static BusinessException error(String c,HttpStatus s){return new BusinessException(c,"真实验证记录暂不可用",s);}
}
